// sketch.ino — ESP32-S3 (USB-OTG)
#include "USB.h"
#include "USBHIDKeyboard.h"
USBHIDKeyboard Keyboard;

// Готовая строка — никаких преобразований на лету
const char* CMD = "dir/s";

void pressEnter() {
  Keyboard.press(KEY_RETURN);
  delay(30);
  Keyboard.releaseAll();
}

void setup() {
  Keyboard.begin();
  USB.begin();
  delay(3000);

  // Win + R -> cmd с зелёным цветом
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(50);
  Keyboard.releaseAll();
  delay(600);

  Keyboard.print("cmd /k color 2");
  pressEnter();
  delay(1500);

  // Первый запуск команды
  Keyboard.print(CMD);
  pressEnter();

  delay(1500);
  Keyboard.press(KEY_F11);   // полный экран
  delay(50);
  Keyboard.releaseAll();
}

void loop() {
  // Бесконечный цикл: Enter на пустой строке повторяет последнюю команду
  pressEnter();
  delay(100);
}
